// Reserved identity for the built-in demo account. Negative IDs can never be
// generated by the CLI's autoincrement tables, which keeps demo data out of
// every publish-cleanup path (remapStudentIDs skips negative IDs).
const (
	demoUsername     = "demo"
	demoStudentID    = -1
	demoCourseYearID = -1
	demoTermID       = -1
)

