const demoAssignmentInstructions = "Write a Python program in `grader.py` that reads a list of scores and prints the average.\n\nThis is a sample assignment for exploring the submissions workflow. Submissions are disabled on the demo account."

// SeedDemo upserts the demo account, its sample course, a grade snapshot, and
// one sample submission assignment. It runs on every startup when a demo
// password is configured, so rotating the password takes effect on restart.
func (s *Store) SeedDemo(password string) error {
	hash, salt, err := portalauth.HashPassword(password)
	if err != nil {
		return err
	}
	now := time.Now().UTC().Format(time.RFC3339)
	acc := portalauth.Account{
		StudentID:         demoStudentID,
		Username:          demoUsername,
		PasswordSalt:      salt,
		PasswordHash:      hash,
		PasswordChangedAt: now,
	}
	if err := upsertAccount(s.db, acc); err != nil {
		return err
	}
	if err := upsertCourse(s.db, demoCourseYearID, demoTermID, "Sample APCSA", "2026-27", "Term 1", now); err != nil {
		return err
	}
	if err := upsertStudentSnapshot(s.db, demoStudentID, demoCourseYearID, demoTermID, []byte(demoSnapshotJSON), now); err != nil {
		return err
	}
	_, err = s.db.Exec(`
		INSERT INTO sub_assignments(course_year_id, term_id, title, language, instructions, expected_filenames, is_open)
		SELECT ?, ?, ?, 'python', ?, 'grader.py', 1
		WHERE NOT EXISTS (SELECT 1 FROM sub_assignments WHERE course_year_id = ? AND term_id = ?)`,
		demoCourseYearID, demoTermID, "Sample Python Assignment", demoAssignmentInstructions,
		demoCourseYearID, demoTermID)
	return err
}

// ClearDemo removes every demo row. It runs at startup when no demo password
// is configured, so disabling the demo also disables the loggable account
// instead of leaving it behind with its last-seeded password.
func (s *Store) ClearDemo() error {
	statements := []struct {
		query string
		args  []any
	}{
		{`DELETE FROM published_accounts WHERE student_pk = ?`, []any{demoStudentID}},
		{`DELETE FROM published_students WHERE student_pk = ?`, []any{demoStudentID}},
		{`DELETE FROM published_courses WHERE course_year_id = ? AND term_id = ?`, []any{demoCourseYearID, demoTermID}},
		{`DELETE FROM sub_assignments WHERE course_year_id = ? AND term_id = ?`, []any{demoCourseYearID, demoTermID}},
	}
	for _, stmt := range statements {
		if _, err := s.db.Exec(stmt.query, stmt.args...); err != nil {
			return err
		}
	}
	return nil
}

// seedDemoMaterials writes the sample course's material files next to the real
// course materials. Existing files with identical content are left untouched,
// and _meta.json is written only when missing so admin-UI edits survive.
func (s *Server) seedDemoMaterials() error {
	dir := s.materialsDir(demoCourseYearID, demoTermID, "Sample APCSA")
	unitDir := filepath.Join(dir, "unit-1")
	if err := os.MkdirAll(unitDir, 0o755); err != nil {
		return err
	}
	files := []struct {
		path    string
		content []byte
	}{
		{filepath.Join(unitDir, "syllabus.md"), demoSyllabus},
		{filepath.Join(unitDir, "getting-started.md"), demoGettingStarted},
	}
	for _, f := range files {
		if existing, err := os.ReadFile(f.path); err == nil && bytes.Equal(existing, f.content) {
			continue
		}
		if err := os.WriteFile(f.path, f.content, 0o644); err != nil {
			return fmt.Errorf("failed to write demo material: %w", err)
		}
	}
	metaPath := filepath.Join(dir, courseMetaFile)
	if _, err := os.Stat(metaPath); os.IsNotExist(err) {
		meta := courseMeta{Categories: []categoryMeta{{ID: "unit-1", Name: "Unit 1"}}}
		if err := writeCourseMeta(dir, meta); err != nil {
			return fmt.Errorf("failed to write demo materials metadata: %w", err)
		}
	}
	return nil
}
